const DISCIPLINE_GUIDES={
 'Língua Portuguesa':{priority:2,focus:'Interpretação e gramática em contexto',practice:'Leia um texto curto e identifique a tese, as inferências e os conectivos. Para os itens de gramática, reescreva duas frases e justifique cada alteração.',check:['Reconheço a regra no texto, sem depender só de palavras isoladas.','Consigo explicar por que as alternativas erradas estão erradas.'],order:'Interpretação e compreensão → gramática → reescrita → redação oficial.'},
 'Raciocínio Lógico e Matemático':{priority:5,focus:'Lógica proposicional e resolução de problemas',practice:'Traduza um enunciado para símbolos ou equações. Resolva de duas formas quando possível e confira a resposta por substituição, tabela ou contraexemplo.',check:['Sei identificar as hipóteses e o que o problema pede.','Consigo justificar a solução e testar casos-limite.'],order:'Proposições e conectivos → tabelas e equivalências → conjuntos → matemática.'},
 'Direito Constitucional':{priority:5,focus:'Constituição e funções essenciais à Justiça',practice:'Leia o dispositivo correspondente em fonte oficial atualizada. Faça um esquema relacionando regra, titular do direito ou competência e exceções.',check:['Localizei os dispositivos pertinentes na Constituição.','Consigo distinguir regra, exceção, órgão e competência.'],order:'Princípios e direitos → organização do Estado e dos Poderes → Ministério Público.'},
 'Direito Administrativo':{priority:5,focus:'Organização, atos, agentes e controle',practice:'Crie um caso prático para o tópico. Identifique o agente, o ato, a competência e o possível controle. Confira a legislação em vigor exigida pelo edital.',check:['Distingo conceitos próximos em situações concretas.','Conferi alterações legislativas antes de usar material antigo.'],order:'Princípios e organização → atos e poderes → agentes → licitações e controle.'},
 'Legislação do Ministério Público':{priority:5,focus:'Estrutura, competências e normas institucionais',practice:'Monte um mapa dos órgãos do MP-MA e suas competências a partir das normas oficiais. Separe as regras sobre membros das regras sobre servidores.',check:['Não confundo atribuições dos diferentes órgãos.','Verifiquei o texto vigente e a norma efetivamente indicada no edital.'],order:'Constituição, arts. 127 a 130-A → Lei 8.625/1993 → normas estaduais e internas.'},
 'Governança e Gestão de TI':{priority:1,focus:'ITIL, COBIT, CMMI e alinhamento de TI',practice:'Descreva uma interrupção de serviço, sua investigação e uma mudança proposta. Identifique quais práticas se aplicam e quais indicadores ajudariam a avaliar o resultado.',check:['Distingo governança de gestão e incidentes de problemas.','Identifico a versão do framework usada na aula ou questão.'],order:'Fundamentos, PETI e PDTI → ITIL → COBIT → CMMI → riscos e projetos.'},
 'Engenharia de Software':{priority:3,focus:'Requisitos, UML, processos e testes',practice:'Escolha um pequeno sistema de chamados. Escreva requisitos, desenhe um diagrama adequado e proponha testes que verifiquem o comportamento esperado.',check:['Distingo requisitos funcionais dos não funcionais.','Justifico o modelo de desenvolvimento, diagrama ou nível de teste escolhido.'],order:'Ciclo de vida → requisitos → orientação a objetos e UML → testes → qualidade e entrega.'},
 'Algoritmos e Estruturas de Dados':{priority:4,focus:'Raciocínio, estruturas e complexidade',practice:'Escreva pseudocódigo para o assunto e faça um teste de mesa. Use entradas normais, vazias e de fronteira; depois estime o custo das operações.',check:['Consigo acompanhar o estado das variáveis em cada passo.','Escolho uma estrutura de dados conforme as operações necessárias.'],order:'Lógica, tipos e operadores → condições e laços → estruturas → busca e ordenação.'},
 'Programação':{priority:4,focus:'Fundamentos, orientação a objetos e web',practice:'Implemente um exemplo pequeno do tópico. Registre a entrada, a saída esperada e um erro possível; explique o código sem olhar a implementação.',check:['Entendo o comportamento, sem decorar apenas a sintaxe.','Sei distinguir conceitos de linguagem, protocolo e arquitetura.'],order:'Estruturada → POO → linguagens → web, APIs e integração.'},
 'Redes de Computadores':{priority:6,focus:'Protocolos, endereçamento e diagnóstico',practice:'Desenhe uma rede pequena e acompanhe uma requisição entre cliente e servidor. Associe os equipamentos, endereços, protocolos e comandos de diagnóstico ao caminho.',check:['Relaciono o conceito à camada e à função correspondente.','Consigo propor um diagnóstico a partir de sintomas e resultados.'],order:'Tipos e topologias → OSI/TCP-IP → IP e sub-redes → protocolos → operação.'},
 'Sistemas Operacionais':{priority:6,focus:'Administração de Windows e Linux',practice:'Em máquina de laboratório, investigue um processo, usuário, permissão ou serviço relacionado ao tópico. Anote o objetivo de cada comando e como conferir o resultado.',check:['Distingo funcionamento interno de tarefas de administração.','Consigo explicar o efeito e o contexto de cada configuração.'],order:'Fundamentos → processos e memória → Windows/Linux → diretório e administração.'},
 'Segurança da Informação':{priority:6,focus:'Riscos, controles, criptografia e continuidade',practice:'Para o assunto estudado, descreva um ativo, uma ameaça, uma vulnerabilidade e um controle. Explique o que esse controle protege e quais limitações ele tem.',check:['Não confundo ameaça, vulnerabilidade, risco e incidente.','Consigo justificar o controle escolhido para um cenário.'],order:'Princípios → riscos e ataques → criptografia e acesso → backup e continuidade.'},
 'Banco de Dados':{priority:7,focus:'Modelagem, SQL e transações',practice:'Modele tabelas de usuários e chamados. Escreva consultas ou operações relacionadas ao tópico e confira resultados com registros que incluam duplicidades e valores nulos.',check:['Sei explicar o efeito da operação nos dados.','Entendo a relação entre modelagem, integridade e consulta.'],order:'Conceitos e modelos → chaves e normalização → SQL → transações e administração.'},
 'Hardware, Manutenção e Suporte Técnico':{priority:7,focus:'Componentes, diagnóstico e atendimento',practice:'Elabore um procedimento de diagnóstico: sintoma, hipóteses, teste, resultado esperado e registro do atendimento. Relacione o componente ao seu papel no computador.',check:['Distingo compatibilidade, desempenho e defeito.','Registro o procedimento e confirmo se o problema foi resolvido.'],order:'Arquitetura e componentes → inicialização → manutenção → suporte e documentação.'},
 'Computação em Nuvem e Infraestrutura':{priority:7,focus:'Modelos de serviço, operação e disponibilidade',practice:'Compare duas formas de implantar um serviço. Identifique o que a equipe administra, o que o provedor oferece e como lidar com falhas, variação de demanda e monitoramento.',check:['Distingo modelo de serviço de modelo de implantação.','Sei explicar disponibilidade, escalabilidade e continuidade no cenário.'],order:'Conceitos e modelos → virtualização e contêineres → disponibilidade → automação.'}
};
function getDeadline(){const target=state.examDate||((state.examMonth||'2027-02')+'-01');return new Date(target+'T12:00:00')}
function deadlineHTML(){let d=getDeadline(),now=new Date(today()+'T12:00:00'),days=Math.max(0,Math.ceil((d-now)/86400000)),remaining=PROGRAM.filter(t=>!state.done[t.id]).length,weeks=Math.max(1,Math.floor((days-7)/7)),month=new Date((state.examMonth||'2027-02')+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return `<section class="deadline"><div><span class="eyebrow">PREPARAÇÃO PARA ${esc(month.toUpperCase())}</span><h3>${state.examDate?days+' dias até a data informada':days+' dias até o início de '+esc(month)}</h3><p>${state.examDate?'Data da prova informada por você.':'Dia da prova a confirmar. Fevereiro de 2027 é a referência provisória; não é uma confirmação de edital.'} ${remaining} assuntos pendentes · referência de ${Math.ceil(remaining/weeks)} por semana, reservando a última semana para revisão.</p></div><details><summary>Ajustar prazo</summary><label>Mês de referência <input type="month" id="exam-month" value="${esc(state.examMonth||'2027-02')}"></label><label>Dia exato, quando souber <input type="date" id="exam-date" value="${esc(state.examDate||'')}"></label><button id="deadline-save">Salvar prazo</button></details></section>`}
function bindDeadline(){$('#deadline-save').onclick=()=>{let month=$('#exam-month').value,date=$('#exam-date').value;if(!month)return toast('Selecione o mês de referência.');if(date&&date.slice(0,7)!==month)return toast('O dia exato precisa pertencer ao mês informado.');state.examMonth=month;state.examDate=date;save();render();toast('Prazo atualizado.')}}
function weeklyHTML(w){let rows=PROGRAM.filter(t=>w===11?!state.done[t.id]:t.week===w);return `<section class="weekly-topics"><div class="week-banner"><div><h3>${w===11?'Revisão final dos assuntos pendentes':'Assuntos detalhados desta semana'}</h3><p>${rows.length} tópicos da lista ampliada. Distribuição sugerida para a primeira passagem; ajuste o ritmo conforme o prazo e a dificuldade.</p></div></div>${rows.length?[...new Set(rows.map(t=>t.category))].map(cat=>{let group=rows.filter(t=>t.category===cat);return `<details class="topic-group"><summary><span>${esc(cat)}</span><span class="pill">${group.filter(t=>state.done[t.id]).length}/${group.length}</span></summary><div class="cards">${group.map(card).join('')}</div></details>`}).join(''):'<div class="empty">Todos os assuntos da lista ampliada estão concluídos. Continue as revisões espaçadas e use o caderno de erros.</div>'}</section>`}
function overviewHTML(){let cats=Object.keys(DISCIPLINE_GUIDES).sort((a,b)=>DISCIPLINE_GUIDES[a].priority-DISCIPLINE_GUIDES[b].priority);const historical=[['Governança de TI',22],['Língua Portuguesa',10],['Engenharia de Software',8],['Programação',6],['Raciocínio Lógico',5],['Legislação do Ministério Público',4],['Algoritmos e Estruturas de Dados',2],['Arquitetura de Software',1],['Segurança da Informação',1],['Legislação Estadual',1]];return `<div class="note">Programa ampliado: ${PROGRAM.length} tópicos em ${cats.length} disciplinas, conforme a lista enviada por você. A prioridade é uma sugestão de preparação. As matérias de um novo concurso dependem do edital.</div><div class="discipline-grid">${cats.map(cat=>{let g=DISCIPLINE_GUIDES[cat],rows=PROGRAM.filter(t=>t.category===cat),n=rows.filter(t=>state.done[t.id]).length;return `<article class="discipline-card"><small>PRIORIDADE ${g.priority} · ${rows.length} ASSUNTOS</small><h3>${esc(cat)}</h3><p>${esc(g.focus)}</p><div class="track"><i style="width:${n/rows.length*100}%"></i></div><p>${n}/${rows.length} concluídos</p><button data-discipline="${esc(cat)}">Estudar disciplina →</button></article>`}).join('')}</div><details class="topic-group"><summary>Por onde começar: sua ordem de prioridade</summary><ol class="priority-list"><li>Governança de TI — ITIL, COBIT e CMMI</li><li>Língua Portuguesa — interpretação e gramática</li><li>Engenharia de Software — requisitos, UML e testes</li><li>Programação e Algoritmos</li><li>Raciocínio Lógico e Legislação do MP-MA</li><li>Redes, Sistemas Operacionais e Segurança</li><li>Banco de Dados, Hardware e Infraestrutura</li></ol></details><details class="topic-group"><summary>Referência histórica: prova FCC de 2013</summary><p>A prova de Técnico Ministerial — Tecnologia da Informação de 2013 tinha 60 questões. A divisão temática abaixo reproduz a classificação do texto que você enviou; não é uma distribuição oficial para uma nova prova e pode variar conforme o critério de classificação.</p><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Questões na classificação enviada</th></tr></thead><tbody>${historical.map(([c,n])=>`<tr><td>${c}</td><td>${n}</td></tr>`).join('')}<tr><th>Total</th><th>60</th></tr></tbody></table></div><p><a target="_blank" rel="noopener" href="https://arquivos.qconcursos.com/prova/arquivo_prova/31886/fcc-2013-mpe-ma-tecnico-ministerial-tecnologia-da-informacao-prova.pdf">Consultar caderno da prova FCC de 2013 ↗</a></p></details>`}
function topicGuideHTML(topic){let g=DISCIPLINE_GUIDES[topic.category]||(topic.id.startsWith('c-')?{order:'Conceitos → exemplos e aplicação → questões → revisão dos erros.',practice:'Estude o assunto na videoaula e, quando houver norma, leia o texto da fonte oficial. Produza um resumo e confira o que mudou em relação ao material de referência.',check:['Distingo os conceitos e consigo aplicá-los a um exemplo.','Conferi a data e o alcance do material e da legislação estudados.']}:null);return `<div class="lesson-meta">${topic.area?`<span class="pill">${esc(topic.area)}</span><span class="pill">Semana sugerida ${topic.week+1}</span>`:''}<span class="pill">${esc(topic.source||'Cronograma original')}</span></div>${careerReadingHTML(topic)}${g?`<details class="topic-group"><summary>Roteiro de estudo desta disciplina</summary><p><b>Sequência:</b> ${esc(g.order)}</p><p><b>Pratique:</b> ${esc(g.practice)}</p><p><b>Antes de concluir “${esc(topic.title)}”:</b></p><ul><li>Consigo definir o conceito e dar um exemplo aplicado.</li>${g.check.map(c=>`<li>${esc(c)}</li>`).join('')}<li>Resolvi questões e anotei meus erros para revisar.</li></ul><p>Este roteiro orienta o estudo; não substitui a aula ou o material teórico do assunto.</p></details>`:''}`}
